use serde_json::{json,Value};
use kfc_kfc_alpha::kfc::xpxml::{hlxml::traversal::HLElementByteParser::{HLElementByteParser,Utf8,Charset},reader::{XmlName2Id::XmlName2Id,XmlRoAttrList::XmlRoAttrList}};
use ss_core::cn::wps::moss::xlsxr::util::MapManager::MapManager;
use std::{sync::{Arc,Mutex},panic::{catch_unwind,AssertUnwindSafe}};
struct Ids;impl XmlName2Id for Ids{fn get_id(&self,p:i32,n:i32)->i32{MapManager::getInstance().getId(p,n)}}
fn call(f:impl FnOnce())->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(())=>json!({"result":"ok","value":null}),Err(e)=>{let t=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");let result=["IllegalStateException","NumberFormatException","ArrayIndexOutOfBoundsException","NullPointerException"].iter().find(|n|t.starts_with(**n)).copied().unwrap_or(t);json!({"result":result})}}}
#[test]
fn original_android_sst_byte_parser(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/sst-blocks-r0b45");let input:Value=serde_json::from_slice(&std::fs::read(root.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(root.join("java.json")).unwrap()).unwrap();let mut parsers=vec![];for p in input["parsers"].as_array().unwrap(){let mut parser=HLElementByteParser::HLElementByteParser(Some(Arc::new(Ids)));let attrs=Arc::new(Mutex::new(XmlRoAttrList::new()));parser.setRoAttr(Some(attrs.clone()));let mut history=vec![];for e in p["elements"].as_array().unwrap(){let bytes=e["text"].as_str().unwrap().as_bytes();let mut r=call(||parser.parseElement(bytes,0,bytes.len()as i32-1,e["type"].as_i64().unwrap()as i32));r["label"]=json!(parser.getLabel());let attrs=attrs.lock().unwrap();r["attrs"]=json!((0..attrs.count()).map(|i|json!([attrs.get_name_at(i as usize),attrs.get_attr_at(i as usize).to_string()])).collect::<Vec<_>>());history.push(r);}parsers.push(json!({"history":history}));}std::fs::write(root.join("rust-parsers.json"),serde_json::to_vec_pretty(&parsers).unwrap()).unwrap();assert_eq!(json!(parsers),java["parsers"]);}
#[test]
fn original_android_utf8_byte_decoding(){
    let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/sst-blocks-r0b45");let java:Value=serde_json::from_slice(&std::fs::read(root.join("java.json")).unwrap()).unwrap();let mut rows=vec![];let mut emit=|b:&[u8]|{let units=Utf8.decode(b).encode_utf16().map(|c|format!("{c:04x}")).collect::<String>();assert_eq!(units,java["utf8"][rows.len()].as_str().unwrap(),"bytes {b:?}");rows.push(units);};for i in 0..65536{emit(&[(i>>8)as u8,i as u8]);}for i in 0..65536{emit(&[0xed,(i>>8)as u8,i as u8]);}for b1 in 0xf0..=0xf5{for b2 in 0..256{for b3 in [0x7f,0x80,0xbf,0xc0]{for b4 in [0x7f,0x80,0xbf,0xc0]{emit(&[b1,b2 as u8,b3,b4]);}}}}assert_eq!(rows.len(),java["utf8"].as_array().unwrap().len());std::fs::write(root.join("rust-utf8.json"),serde_json::to_vec(&rows).unwrap()).unwrap();
}
